python - <<'PY'
import numpy as np
from PIL import Image
D=np.load('/app/output/stroke_masks.npz',allow_pickle=True);M=D['masks']>127;T=np.asarray(Image.open('/app/target.png').convert('RGB')).mean(2)<100
cases={0:[280,290,300,310,320,340,360,380,400,420,430],1:[350,360,370,380,390,400],2:[220,230,240,250,260,270,280,300,320,350,400,450,500,550,570,580],3:[430,440,450],4:[490,500,510,520],5:[550,560,570,580,590,600],6:[620,630,640,650,680,700,740,760,780],7:[650,700,750,780,790],8:[690,700,710],9:[760,770,780,790]}
def runs(a):
 xs=np.where(a)[0];out=[]
 if len(xs):
  s=p=xs[0]
  for x in xs[1:]:
   if x>p+1:out.append((int(s),int(p)));s=x
   p=x
  out.append((int(s),int(p)))
 return out
for i,rows in cases.items():
 print('\nSTROKE',i)
 for y in rows:
  t=runs(T[y]);c=runs(M[i,y]);
  if c:print(y,'T',t,'C',c)
PY
